1	import request from "graphql-request";
2	import { DispatchedTxnData, HashiMessageExecutionVars } from "./hashiTypes";
3	import { DataError, MissingEnvironmentVariable } from "../errors";
4	
5	const DEFAULT_BATCH_SIZE = 10;
6	
7	interface EnvioMessageDispatched {
8	  messageId: string;
9	  txHash: string;
10	  sourceChainId: string;
11	  yaho: string;
12	  nonce: string;
13	  targetChainId: string;
14	  threshold: string;
15	  sender: string;
16	  receiver: string;
17	  data: string;
18	  reporters: string;
19	  adapters: string;
20	  blockNumber: string;
21	  blockTimestamp: string;
22	}
23	
24	interface EnvioDispatchedResponse {
25	  MessageDispatched: EnvioMessageDispatched[];
26	  chain_metadata: { latest_processed_block: number }[];
27	}
28	
29	const dispatchedMessagesQuery = `
30	  query DispatchedMessages($sourceChainId: numeric!, $targetChainId: numeric!, $chainId: Int!, $yaho: String!, $fromBlock: numeric!, $limit: Int!) {
31	    MessageDispatched(
32	      where: {
33	        sourceChainId: { _eq: $sourceChainId }
34	        targetChainId: { _eq: $targetChainId }
35	        yaho: { _ilike: $yaho }
36	        blockNumber: { _gt: $fromBlock }
37	      }
38	      order_by: { blockNumber: asc }
39	      limit: $limit
40	    ) {
41	      messageId
42	      txHash
43	      sourceChainId
44	      yaho
45	      nonce
46	      targetChainId
47	      threshold
48	      sender
49	      receiver
50	      data
51	      reporters
52	      adapters
53	      blockNumber
54	      blockTimestamp
55	    }
56	    chain_metadata(where: { chain_id: { _eq: $chainId } }) {
57	      latest_processed_block
58	    }
59	  }
60	`;
61	
62	/**
63	 * Map an Envio MessageDispatched row to the executor's HashiMessageExecutionVars shape.
64	 * @param row The raw MessageDispatched entity returned by the Envio indexer
65	 * @returns The HashiMessageExecutionVars for the executor
66	 */
67	function toHashiMessageExecutionVars(row: EnvioMessageDispatched): HashiMessageExecutionVars {
68	  return {
69	    txHash: row.txHash,
70	    timestamp: Number(row.blockTimestamp),
71	    blockNumber: Number(row.blockNumber),
72	    messageId: BigInt(row.messageId),
73	    message: {
74	      nonce: Number(row.nonce),
75	      sender: row.sender,
76	      targetChainId: Number(row.targetChainId),
77	      receiver: row.receiver,
78	      threshold: Number(row.threshold),
79	      data: row.data,
80	      reporters: JSON.parse(row.reporters),
81	      adapters: JSON.parse(row.adapters),
82	    },
83	  };
84	}
85	
86	/**
87	 * Get MessageDispatched events from the Envio Yaho indexer starting after a specific block
88	 * @param sourceChainId The chain ID of the Yaho (source) chain
89	 * @param targetChainId The chain ID the messages are destined for; other routes' messages are excluded
90	 * @param yahoAddress The Yaho contract address
91	 * @param fromBlock The last processed block number; only events strictly after it are returned
92	 * @param batchSize The maximum number of messages to fetch (default: 10)
93	 * @returns The dispatched messages and the block number to checkpoint in the state file
94	 */
95	async function getDispatchedMessagesFromEnvio(
96	  sourceChainId: number,
97	  targetChainId: number,
98	  yahoAddress: string,
99	  fromBlock: number,
100	  batchSize = DEFAULT_BATCH_SIZE
101	): Promise<DispatchedTxnData> {
102	  const envioEndpoint = process.env.RELAYER_ENVIO_YAHO;
103	  if (!envioEndpoint) {
104	    throw new MissingEnvironmentVariable("RELAYER_ENVIO_YAHO");
105	  }
106	  try {
107	    const result = (await request(envioEndpoint, dispatchedMessagesQuery, {
108	      sourceChainId,
109	      targetChainId,
110	      chainId: sourceChainId,
111	      yaho: yahoAddress,
112	      fromBlock,
113	      limit: batchSize,
114	    })) as EnvioDispatchedResponse;
115	
116	    const txns = result.MessageDispatched.map(toHashiMessageExecutionVars);
117	
118	    // A full batch may have been truncated mid-range, so only checkpoint up to
119	    // the last fetched message; otherwise the indexer head is safe to checkpoint.
120	    const indexerHead = result.chain_metadata[0]?.latest_processed_block;
121	    let toBlock = fromBlock;
122	    if (txns.length === batchSize) {
123	      toBlock = txns[txns.length - 1].blockNumber;
124	    } else if (indexerHead !== undefined) {
125	      toBlock = Math.max(indexerHead, fromBlock);
126	    } else if (txns.length > 0) {
127	      toBlock = txns[txns.length - 1].blockNumber;
128	    }
129	
130	    return { txns, toBlock };
131	  } catch (e) {
132	    throw new DataError("Failed to fetch dispatched messages (envio)", sourceChainId, "hashi", { cause: e });
133	  }
134	}
135	
136	export { getDispatchedMessagesFromEnvio, toHashiMessageExecutionVars, EnvioMessageDispatched };
