4	jest.mock("graphql-request", () => ({
5	  __esModule: true,
6	  default: jest.fn(),
7	}));
8	
9	const mockRequest = request as jest.MockedFunction<typeof request>;
10	
11	const makeEnvioRow = (overrides: Partial<EnvioMessageDispatched> = {}): EnvioMessageDispatched => ({
12	  messageId: "12345",
13	  txHash: "0xTxHash",
14	  sourceChainId: "1514",
15	  yaho: "0xYAHO",
16	  nonce: "3",
17	  targetChainId: "42161",
18	  threshold: "2",
19	  sender: "0xSender",
20	  receiver: "0xReceiver",
21	  data: "0xData",
22	  reporters: JSON.stringify(["0xReporter1"]),
23	  adapters: JSON.stringify(["0xAdapter1", "0xAdapter2"]),
24	  blockNumber: "100",
25	  blockTimestamp: "1700000000",
26	  ...overrides,
27	});
28	
29	describe("envioQueries", () => {
30	  const sourceChainId = 1514;
31	  const targetChainId = 42161;
32	  const yahoAddress = "0xYAHO";
33	  const fromBlock = 50;
34	
35	  beforeEach(() => {
36	    jest.clearAllMocks();
37	    process.env.RELAYER_ENVIO_YAHO = "http://envio.test/v1/graphql";
38	  });
39	
40	  afterAll(() => {
41	    delete process.env.RELAYER_ENVIO_YAHO;
42	  });
43	
44	  describe("toHashiMessageExecutionVars", () => {
45	    it("should map an Envio row to HashiMessageExecutionVars", () => {
46	      const mapped = toHashiMessageExecutionVars(makeEnvioRow());
47	      expect(mapped).toEqual({
48	        txHash: "0xTxHash",
49	        timestamp: 1700000000,
50	        blockNumber: 100,
51	        messageId: BigInt(12345),
52	        message: {
53	          nonce: 3,
54	          sender: "0xSender",
55	          targetChainId: 42161,
56	          receiver: "0xReceiver",
57	          threshold: 2,
58	          data: "0xData",
59	          reporters: ["0xReporter1"],
60	          adapters: ["0xAdapter1", "0xAdapter2"],
61	        },
62	      });
63	    });
64	  });
65	
66	  describe("getDispatchedMessagesFromEnvio", () => {
67	    it("should throw MissingEnvironmentVariable when RELAYER_ENVIO_YAHO is not set", async () => {
68	      delete process.env.RELAYER_ENVIO_YAHO;
69	      await expect(
70	        getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock)
71	      ).rejects.toThrow("Missing environment variable: RELAYER_ENVIO_YAHO");
72	      expect(mockRequest).not.toHaveBeenCalled();
73	    });
74	
75	    it("should query the indexer with the source chain, yaho address and fromBlock", async () => {
76	      mockRequest.mockResolvedValue({
77	        MessageDispatched: [],
78	        chain_metadata: [{ latest_processed_block: 200 }],
79	      });
80	      await getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock);
81	      expect(mockRequest).toHaveBeenCalledWith("http://envio.test/v1/graphql", expect.any(String), {
82	        sourceChainId,
83	        targetChainId,
84	        chainId: sourceChainId,
85	        yaho: yahoAddress,
86	        fromBlock,
87	        limit: 10,
88	      });
89	    });
90	
91	    it("should checkpoint the indexer head when the batch is not full", async () => {
92	      mockRequest.mockResolvedValue({
93	        MessageDispatched: [makeEnvioRow()],
94	        chain_metadata: [{ latest_processed_block: 200 }],
95	      });
96	      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
97	        sourceChainId,
98	        targetChainId,
99	        yahoAddress,
100	        fromBlock
101	      );
102	      expect(txns).toHaveLength(1);
103	      expect(txns[0].message.nonce).toBe(3);
104	      expect(toBlock).toBe(200);
105	    });
106	
107	    it("should checkpoint the last fetched message when the batch is full", async () => {
108	      const rows = Array.from({ length: 10 }, (_, i) =>
109	        makeEnvioRow({ nonce: String(i), blockNumber: String(100 + i) })
110	      );
111	      mockRequest.mockResolvedValue({
112	        MessageDispatched: rows,
113	        chain_metadata: [{ latest_processed_block: 500 }],
114	      });
115	      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
116	        sourceChainId,
117	        targetChainId,
118	        yahoAddress,
119	        fromBlock
120	      );
121	      expect(txns).toHaveLength(10);
122	      expect(toBlock).toBe(109);
123	    });
124	
125	    it("should not move the checkpoint backwards when the indexer head lags fromBlock", async () => {
126	      mockRequest.mockResolvedValue({
127	        MessageDispatched: [],
128	        chain_metadata: [{ latest_processed_block: 40 }],
129	      });
130	      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
131	        sourceChainId,
132	        targetChainId,
133	        yahoAddress,
134	        fromBlock
135	      );
136	      expect(txns).toHaveLength(0);
137	      expect(toBlock).toBe(fromBlock);
138	    });
139	
140	    it("should checkpoint the last fetched message when chain metadata is missing", async () => {
141	      mockRequest.mockResolvedValue({
142	        MessageDispatched: [makeEnvioRow({ blockNumber: "120" })],
143	        chain_metadata: [],
144	      });
145	      const { toBlock } = await getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock);
146	      expect(toBlock).toBe(120);
147	    });
148	
149	    it("should keep fromBlock when there are no messages and no chain metadata", async () => {
150	      mockRequest.mockResolvedValue({
151	        MessageDispatched: [],
152	        chain_metadata: [],
153	      });
154	      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
155	        sourceChainId,
156	        targetChainId,
157	        yahoAddress,
158	        fromBlock
159	      );
160	      expect(txns).toHaveLength(0);
161	      expect(toBlock).toBe(fromBlock);
162	    });
163	
164	    it("should wrap indexer failures in DataError", async () => {
165	      mockRequest.mockRejectedValue(new Error("connection refused"));
166	      await expect(
167	        getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock)
168	      ).rejects.toMatchObject({
169	        name: "DataError",
170	        message: "Data error for call: Failed to fetch dispatched messages (envio), Chain ID: 1514, Network: hashi",
171	      });
172	    });
173	  });
174	});
