const mockRequest = request as jest.MockedFunction<typeof request>;
// Untyped view of the same mock, so implementations can branch on the GraphQL variables.
const mockRequestFn = request as unknown as jest.Mock;

type EnvioVariables = {
  fromBlock?: number;
  blockNumber?: number;
  limit: number;
  offset?: number;
};

/**
 * Mimic the indexer: sort by (blockNumber, id) like the queries ask for, then serve either
 * the main `blockNumber > fromBlock` page or the per-block `blockNumber == blockNumber`
 * drain page, depending on which variables the caller passed.
 */
const mockIndexer = (allRows: EnvioMessageDispatched[], latestProcessedBlock: number) => {
  const ordered = [...allRows].sort(
    (a, b) => Number(a.blockNumber) - Number(b.blockNumber) || a.id.localeCompare(b.id)
  );
  mockRequestFn.mockImplementation((_url: string, _query: string, variables: EnvioVariables) => {
    if (variables.blockNumber !== undefined) {
      const blockRows = ordered.filter((row) => Number(row.blockNumber) === Number(variables.blockNumber));
      const offset = variables.offset ?? 0;
      return Promise.resolve({ MessageDispatched: blockRows.slice(offset, offset + variables.limit) });
    }
    const afterCursor = ordered.filter((row) => Number(row.blockNumber) > Number(variables.fromBlock));
    return Promise.resolve({
      MessageDispatched: afterCursor.slice(0, variables.limit),
      chain_metadata: [{ latest_processed_block: latestProcessedBlock }],
    });
  });
};

